176			_ = tmp.Chmod(info.Mode().Perm())
177		}
178		if _, err := tmp.Write(data); err != nil {
179			_ = tmp.Close()
180			return err
181		}
182		if err := tmp.Sync(); err != nil {
183			_ = tmp.Close()
184			return err
185		}
186		if err := tmp.Close(); err != nil {
187			return err
188		}
189		return os.Rename(tmpName, path)
190	}
191	
192	// handleStateUnavailable answers the state endpoints of handlers wired
193	// without a state file: every method gets 503 state_unavailable.
194	func handleStateUnavailable(w http.ResponseWriter, r *http.Request) {
195		w.Header().Set("Content-Type", "application/json; charset=utf-8")
196		writeValidation(w, http.StatusServiceUnavailable, []validationError{{
197			Code:    codeStateUnavailable,
198			Message: "state endpoints require a state file; use HandlerWithProviderAndStateFile",
199			Path:    "",
200		}})
201	}
202	
203	// stateResponse is the GET /v1/state payload.
204	type stateResponse struct {
205		Revision int64          `json:"revision"`
206		State    *stateDocument `json:"state"`
207	}
208	
209	// handleRead serves GET /v1/state: the current revision and the stored
210	// state document, normalized like an apply run's output state.
211	func (b *stateBackend) handleRead(w http.ResponseWriter, r *http.Request) {
212		w.Header().Set("Content-Type", "application/json; charset=utf-8")
213		if r.Method != http.MethodGet {
214			w.Header().Set("Allow", http.MethodGet)
215			w.WriteHeader(http.StatusMethodNotAllowed)
216			_ = json.NewEncoder(w).Encode(map[string]any{
217				"error": map[string]string{"code": "method_not_allowed"},
218			})
219			return
220		}
221	
222		current, err := readStateFile(b.path)
223		if err != nil {
224			writeValidation(w, http.StatusInternalServerError, []validationError{{
225				Code:    codeStateReadError,
226				Message: "state file cannot be read or does not hold a valid state document",
227				Path:    "",
228			}})
229			return
230		}
231	
232		w.WriteHeader(http.StatusOK)
233		_ = json.NewEncoder(w).Encode(stateResponse{
234			Revision: current.revision,
235			State:    renderState(seedState(current.resources)),
236		})
237	}
238	
239	// stateApplyResponse is the POST /v1/state/apply payload. Revision reports
240	// the file's revision after the run (unchanged when nothing was committed);
241	// CurrentRevision is set only on an expectedRevision conflict.
242	type stateApplyResponse struct {
243		Valid           bool              `json:"valid"`
244		Errors          []validationError `json:"errors"`
245		Applied         *[]planChange     `json:"applied,omitempty"`
246		Summary         planSummary       `json:"summary"`
247		State           *stateDocument    `json:"state,omitempty"`
248		Revision        *int64            `json:"revision,omitempty"`
249		CurrentRevision *int64            `json:"currentRevision,omitempty"`
250	}
251	
252	// handleApply serves POST /v1/state/apply: it plans the submitted
253	// configuration against the state file and executes under the file's
254	// non-blocking exclusive lock, committing the evolved state atomically.
255	func (b *stateBackend) handleApply(source providerSource) http.HandlerFunc {
256		return func(w http.ResponseWriter, r *http.Request) {
257			w.Header().Set("Content-Type", "application/json; charset=utf-8")
258			if r.Method != http.MethodPost {
259				rejectMethodNotAllowed(w)
260				return
261			}
262	
263			doc, ok := decodeConfigurationBody(w, r)
264			if !ok {
265				return
266			}
267			configRaw, expectedRevision, ok := checkStateApplyEnvelope(w, doc)
268			if !ok {
269				return
270			}
271	
272			// The configuration is validated exactly like the plan endpoint's,
273			// with findings rooted at /configuration.
274			var errs []validationError
275			var configResources []planResource
276			var configOrder []string
277			if baseErrs := validateConfiguration(configRaw); len(baseErrs) != 0 {
278				errs = appendPrefixedErrors(errs, baseErrs, "/configuration")
279			} else if order, depErrs := orderConfiguration(configRaw); len(depErrs) != 0 {
280				errs = appendPrefixedErrors(errs, depErrs, "/configuration")
281			} else {
282				configResources = configurationResources(configRaw)
283				configOrder = order
284			}
285			if len(errs) != 0 {
286				sortValidationErrors(errs)
287				writeValidation(w, http.StatusUnprocessableEntity, errs)
288				return
289			}
290	
291			// The lock spans the run from read to commit; every outcome below
292			// releases it via the deferred unlock.
293			unlock, acquired := tryLockState(b.path)
294			if !acquired {
295				writeValidation(w, http.StatusConflict, []validationError{{
296					Code:    codeStateLocked,
297					Message: "state file is locked by another apply run",
298					Path:    "",
299				}})
300				return
301			}
302			defer unlock()
303	
304			current, err := readStateFile(b.path)
305			if err != nil {
306				writeValidation(w, http.StatusInternalServerError, []validationError{{
307					Code:    codeStateReadError,
308					Message: "state file cannot be read or does not hold a valid state document",
309					Path:    "",
310				}})
311				return
312			}
313	
314			if expectedRevision != nil && *expectedRevision != current.revision {
315				currentRevision := current.revision
316				w.WriteHeader(http.StatusConflict)
317				_ = json.NewEncoder(w).Encode(stateApplyResponse{
318					Valid: false,
319					Errors: []validationError{{
320						Code:    codeStateConflict,
321						Message: "expectedRevision does not match the current state revision",
322						Path:    "/expectedRevision",
323					}},
324					CurrentRevision: &currentRevision,
325				})
326				return
327			}
328	
329			changes, summary := computePlan(configResources, configOrder, current.resources, current.order)
330			state := seedState(current.resources)
331	
332			if len(changes) == 0 {
333				// An empty plan succeeds without a Provider and leaves the file
334				// and its revision untouched.
335				revision := current.revision
336				w.WriteHeader(http.StatusOK)
337				_ = json.NewEncoder(w).Encode(stateApplyResponse{
338					Valid:    true,
339					Errors:   []validationError{},
340					Applied:  &[]planChange{},
341					Summary:  summary,
342					State:    renderState(state),
343					Revision: &revision,
344				})
345				return
346			}
347	
348			// Precheck: every change must route to a registered Provider before
349			// anything executes. An unroutable change aborts the whole run
350			// without calling any Provider and leaves the file and its revision
351			// untouched.
352			providers := make([]Provider, len(changes))
353			for i, change := range changes {
354				typ := changeType(change)
355				provider, registered := source.providerFor(typ)
356				if !registered {
357					revision := current.revision
358					w.WriteHeader(http.StatusServiceUnavailable)
359					_ = json.NewEncoder(w).Encode(stateApplyResponse{
360						Valid:    false,
361						Errors:   []validationError{source.applyUnavailable(typ, i)},
362						Summary:  summary,
363						Revision: &revision,
364					})
365					return
366				}
367				providers[i] = provider
368			}
369	
370			applied := []planChange{}
371			var providerErr error
372			var failIndex int
373			// One fresh idempotency key per non-noop change of this top-level
374			// request; retries reuse a change's key under the held state lock.
375			keys := mintIdempotencyKeys(len(changes))
376			for i, change := range changes {
377				// executeChange applies the controlled retry policy serially;
378				// the lock stays held across every attempt. On failure the run
379				// stops immediately: later changes are skipped, earlier ones are
380				// not rolled back.
381				if err := executeChange(r.Context(), providers[i], change, keys[i]); err != nil {
382					providerErr = err
383					failIndex = i
384					break
385				}
386				applied = append(applied, change)
387				applyToState(state, change)
388			}
389	
390			// Commit when the run has something to persist: every change
391			// succeeded, or a Provider failure left at least one success behind.
392			// A first-change failure keeps the file untouched.
393			committed := false
394			if providerErr == nil || len(applied) > 0 {
395				if err := writeStateFile(b.path, current.revision+1, state); err != nil {
396					// The commit failed; the file keeps its old revision. The
397					// response still carries the executed changes and the state
398					// that could not be persisted.
399					revision := current.revision
400					w.WriteHeader(http.StatusInternalServerError)
401					_ = json.NewEncoder(w).Encode(stateApplyResponse{
402						Valid: false,
403						Errors: []validationError{{
404							Code:    codeStateWriteError,
405							Message: "state file could not be replaced atomically",
406							Path:    "",
407						}},
408						Applied:  &applied,
409						Summary:  summary,
410						State:    renderState(state),
411						Revision: &revision,
412					})
413					return
414				}
415				committed = true
416			}
417	
418			if providerErr != nil {
419				revision := current.revision
420				if committed {
421					// Partial state was persisted and takes exactly one version
422					// increment.
423					revision = current.revision + 1
424				}
425				w.WriteHeader(http.StatusBadGateway)
426				_ = json.NewEncoder(w).Encode(stateApplyResponse{
427					Valid:    false,
428					Errors:   []validationError{{Code: codeProviderError, Message: providerErr.Error(), Path: fmt.Sprintf("/changes/%d", failIndex)}},
429					Applied:  &applied,
430					Summary:  summary,
431					State:    renderState(state),
432					Revision: &revision,
433				})
434				return
435			}
436	
437			revision := current.revision + 1
438			w.WriteHeader(http.StatusOK)
439			_ = json.NewEncoder(w).Encode(stateApplyResponse{
440				Valid:    true,
441				Errors:   []validationError{},
442				Applied:  &applied,
443				Summary:  summary,
444				State:    renderState(state),
445				Revision: &revision,
446			})
447		}
448	}
449	
450	// checkStateApplyEnvelope validates the state-apply request envelope: a JSON
451	// object holding exactly the required configuration field and an optional
452	// expectedRevision that must be a non-negative integer. On failure it writes
453	// the 422 invalid_state_request response and returns ok=false.
454	func checkStateApplyEnvelope(w http.ResponseWriter, doc any) (configuration any, expectedRevision *int64, ok bool) {
455		var errs []validationError
456		add := func(code, message, path string) {
457			errs = append(errs, validationError{Code: code, Message: message, Path: path})
458		}
459	
460		root, isObject := doc.(map[string]any)
461		if !isObject {
462			add(codeInvalidStateRequest, "request body must be a JSON object", "")
463		} else {
464			for key := range root {
465				if key != "configuration" && key != "expectedRevision" {
466					add(codeInvalidStateRequest, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
467				}
468			}
469			var hasConfig bool
470			configuration, hasConfig = root["configuration"]
471			if !hasConfig {
472				add(codeInvalidStateRequest, `missing required field "configuration"`, "")
473			}
474			if revRaw, has := root["expectedRevision"]; has {
475				if revision, valid := nonNegativeInt64(revRaw); valid {
476					expectedRevision = &revision
477				} else {
478					add(codeInvalidStateRequest, `"expectedRevision" must be a non-negative integer`, "/expectedRevision")
479				}
480			}
481		}
482	
483		if len(errs) != 0 {
484			sortValidationErrors(errs)
485			writeValidation(w, http.StatusUnprocessableEntity, errs)
486			return nil, nil, false
487		}
488		return configuration, expectedRevision, true
489	}
