	}
	closed := `{
	  "resourceTypes": [{"name": "t", "schema": {"type": "object", "properties": {"cpu": {"type": "object", "additionalProperties": true}}, "additionalProperties": false}}],
	  "resources": [{"address": "a", "type": "t", "properties": {"cpu": {"$variable": "size"}, "extra": 1}}]
